    public static function list_bridges(WP_REST_Request $r):WP_REST_Response|WP_Error{global $wpdb;$actor=get_current_user_id();$conversation=absint($r->get_param('conversation_id'));if(!self::conversation_manager($conversation,$actor))return self::error('forbidden','Conversation management permission is required.',403);$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE feature_id='F17-FUT-24' AND scope_type='conversation' AND scope_id=%d AND state='active' ORDER BY id DESC LIMIT 100",$conversation));$items=[];foreach(is_array($rows)?$rows:[] as $row){$d=self::decode($row);if(is_wp_error($d)||($d['subtype']??'')!=='bridge')continue;$items[]=['id'=>(int)$row->id,'bridge'=>self::public_bridge($d)];}return rest_ensure_response(['conversation_id'=>$conversation,'items'=>$items]);}
