d_accepted',['bridge_id'=>(int)$bridge->id,'conversation_id'=>(int)$bridge->scope_id,'external_event_id'=>$event_id,'sanitized_payload'=>$decision['payload']??[],'receipt_id'=>$id]);}SN_DB::audit('future_interop_inbound','conversation',(int)$bridge->scope_id,$state==='allow'?'success':'failure',['bridge_id'=>(int)$bridge->id,'receipt_id'=>$id,'decision'=>$state],0);return new WP_REST_Response(['accepted'=>$state==='allow','quarantined'=>$state==='quarantine','receipt_id'=>$id],$state==='allow'?202:($state==='quarantine'?202:403));}
    public static function outbound(WP_REST_Request $r):WP_REST_Response|WP_Error{global $wpdb;$actor=get_current_user_id();$bridge=self::bridge(absint($r['id']));if(!$bridge)return self::not_found();if(!self::conversation_manager((int)$bridge->scope_id,$actor))return self::error('forbidden','Conversation management permission is required.',403);if(!SN_Policy::consume_rate_limit('interop_outbound',(string)$bridge->id,120,MINUTE_IN_SECONDS))return self::error('sn_interop_rate_limited','Interoperability rate limit exceeded.',429);$message=absint($r->get_param('message_id'));$m=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.SN_DB::table('messages').' WHERE id=%d',$message));if(!$m||(int)$m->conversation_id!==(int)$bridge->scope_id||!empty($m->deleted_at)||SN_Message_Operations::is_hidden($actor,$message))return self::not_found();$d=self::decode($bridge);if(is_wp_error($d))return $d;$decision=apply_filters('sn_network_interop_outbound_filter',null,$message,$m,$d,$actor);if(!is_array($decision)||empty($decision['allow']))return self::error('sn_interop_outbound_denied','Outbound bridge policy did not approve this message.',403);$provider=apply_filters('sn_network_interop_outbound_result',null,$d,$decision,$message,$actor);if($provider===null||$provider===false)return self::error('sn_interop_provider_unavailable','Interoperability provider is unavailable.',503);if(is_wp_error($provider))return $provider;SN_DB::audit('future_interop_outbound','message',$message,'success',['bridge_id'=>(int)$bridge->id,'payload_hash'=>hash('sha256',(string)wp_json_encode($decision))],$actor);return rest_ensure_response(['queued'=>true,'bridge_id'=>(int)$bridge->id,'message_id'=>$message]);}
