    private static function create_record(int $owner,int $conversation,array $data,string $client):int|WP_Error{global $wpdb;$key=hash('sha256',$client);$existing=(int)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.$wpdb->prefix.'sn_future_records WHERE client_key=%s',$key));if($existing)return $existing;$dummy=(object)['feature_id'=>'F17-FUT-24','owner_id'=>$owner,'scope_type'=>'conversation','scope_id'=>$conversation];$cipher=self::encode($dummy,$data);if(is_wp_error($cipher))return $cipher;$now=current_time('mysql',true);$ok=$wpdb->insert($wpdb->prefix.'sn_future_records',['feature_id'=>'F17-FUT-24','owner_id'=>$owner,'scope_type'=>'conversation','scope_id'=>$conversation,'state'=>'active','payload_cipher'=>$cipher,'client_key'=>$key,'created_at'=>$now,'updated_at'=>$now,'version'=>1]);return $ok===false?self::error('database_error','Interoperability state could not be stored safely.',500):(int)$wpdb->insert_id;}
